using System.Collections.Generic;
using CourtSim.Core.Presentation;
using CourtSim.Runtime.Common;
using UnityEngine;

namespace CourtSim.Runtime.Audio
{
    /// <summary>
    /// Plays the game's sound effects (<see cref="SoundCue"/>) from anywhere with one line, e.g.
    /// <c>SoundEffects.Play(SoundCue.Gavel)</c>, and runs the looping menu drone.
    /// </summary>
    /// <remarks>
    /// <para>The sounds are generated by <see cref="SfxSynth"/> the first time each is needed and then kept, so there
    /// are no audio files. The component creates itself on first use (a hidden object that survives scene loads),
    /// which is why callers never need a reference to it.</para>
    /// <para>A few audio sources are shared round-robin, so overlapping effects (a gavel during a whoosh) both play.
    /// All sources are 2D: effects are part of the presentation, not sounds from a place in the room.</para>
    /// <para>Nothing plays in batch mode (command-line builds and test runs) or when <see cref="Enabled"/> is false;
    /// every call then simply does nothing, so callers never need to check.</para>
    /// </remarks>
    [DisallowMultipleComponent]
    public sealed class SoundEffects : MonoBehaviour
    {
        /// <summary>Drone loudness under the main menu: there, but quiet enough to talk over.</summary>
        public const float MenuDroneVolume = 0.22f;

        /// <summary>Drone loudness during the opening titles, where it carries the mood.</summary>
        public const float IntroDroneVolume = 0.45f;

        private const int Voices = 4;

        /// <summary>Sweeping the mouse over a column of buttons should tick, not rattle.</summary>
        private const float MinSecondsBetweenHovers = 0.05f;

        private static SoundEffects _instance;
        private static bool _enabled = true;

        [Range(0f, 1f)]
        [SerializeField] private float _masterVolume = 0.8f;

        private readonly Dictionary<SoundCue, AudioClip> _clips = new Dictionary<SoundCue, AudioClip>();
        private AudioSource[] _voices;
        private int _nextVoice;
        private AudioSource _drone;
        private float _droneTarget;
        private float _droneFadeSpeed;
        private float _lastHoverTime = -1f;

        /// <summary>Switches every sound effect off (and stops any playing), e.g. for a "mute effects" setting.</summary>
        public static bool Enabled
        {
            get => _enabled;
            set
            {
                _enabled = value;
                if (!value && _instance != null)
                {
                    _instance.StopEverything();
                }
            }
        }

        /// <summary>True while the drone is audible or fading.</summary>
        public static bool IsDronePlaying => _instance != null && _instance._drone.isPlaying;

        /// <summary>Plays <paramref name="cue"/> once. <paramref name="volume"/> is 0..1 on top of the master volume.</summary>
        public static void Play(SoundCue cue, float volume = 1f)
        {
            SoundEffects effects = GetInstance();
            if (effects != null)
            {
                effects.PlayOnce(cue, volume);
            }
        }

        /// <summary>
        /// Fades the looping drone in to <paramref name="volume"/> over <paramref name="fadeSeconds"/>. If it is already
        /// playing it just glides to the new volume, so calling this again is safe and never restarts the loop.
        /// </summary>
        public static void StartDrone(float volume = MenuDroneVolume, float fadeSeconds = 2f)
        {
            SoundEffects effects = GetInstance();
            if (effects != null)
            {
                effects.FadeDrone(Mathf.Clamp01(volume), fadeSeconds);
            }
        }

        /// <summary>Fades the drone out over <paramref name="fadeSeconds"/> and then stops it.</summary>
        public static void StopDrone(float fadeSeconds = 1.5f)
        {
            if (_instance != null)
            {
                _instance.FadeDrone(0f, fadeSeconds);
            }
        }

        /// <summary>Cuts every one-shot effect immediately (the drone carries on), e.g. when the intro is skipped.</summary>
        public static void StopOneShots()
        {
            if (_instance == null)
            {
                return;
            }

            foreach (AudioSource voice in _instance._voices)
            {
                voice.Stop();
            }
        }

        /// <summary>Static state survives between play sessions when domain reload is off; start each one fresh.</summary>
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetSharedState()
        {
            _instance = null;
        }

        /// <summary>The one instance, created on first use; null whenever sound should not play.</summary>
        private static SoundEffects GetInstance()
        {
            if (!_enabled || !Application.isPlaying || Application.isBatchMode)
            {
                return null;
            }

            if (_instance == null)
            {
                var go = new GameObject("SoundEffects");
                DontDestroyOnLoad(go);
                _instance = go.AddComponent<SoundEffects>();
            }

            return _instance;
        }

        private void Awake()
        {
            _voices = new AudioSource[Voices];
            for (int i = 0; i < Voices; i++)
            {
                _voices[i] = CreateSource();
            }

            _drone = CreateSource();
            _drone.loop = true;
            _drone.priority = 200; // background: the first sound to give way if the mixer runs out of voices
        }

        private void Update()
        {
            if (!_drone.isPlaying)
            {
                return;
            }

            _drone.volume = Mathf.MoveTowards(_drone.volume, _droneTarget, _droneFadeSpeed * Time.unscaledDeltaTime);
            if (_droneTarget <= 0f && _drone.volume <= 0f)
            {
                _drone.Stop();
            }
        }

        private void OnDestroy()
        {
            foreach (AudioClip clip in _clips.Values)
            {
                UnityObjectUtil.SafeDestroy(clip);
            }

            _clips.Clear();
            if (_instance == this)
            {
                _instance = null;
            }
        }

        private AudioSource CreateSource()
        {
            AudioSource source = gameObject.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.spatialBlend = 0f;
            source.ignoreListenerPause = true; // effects belong to the menus too, which work while paused
            return source;
        }

        private void PlayOnce(SoundCue cue, float volume)
        {
            if (cue == SoundCue.UiHover)
            {
                float now = Time.unscaledTime;
                if (now >= _lastHoverTime && now - _lastHoverTime < MinSecondsBetweenHovers)
                {
                    return;
                }

                _lastHoverTime = now;
            }

            // Prefer a free voice; if all are busy, the oldest-started one gives way.
            int chosen = _nextVoice;
            for (int i = 0; i < Voices; i++)
            {
                int index = (_nextVoice + i) % Voices;
                if (!_voices[index].isPlaying)
                {
                    chosen = index;
                    break;
                }
            }

            _nextVoice = (chosen + 1) % Voices;
            AudioSource voice = _voices[chosen];
            voice.clip = GetClip(cue);
            voice.volume = Mathf.Clamp01(volume) * _masterVolume;
            voice.Play();
        }

        private void FadeDrone(float volume, float fadeSeconds)
        {
            float target = volume * _masterVolume;
            if (!_drone.isPlaying)
            {
                if (target <= 0f)
                {
                    return;
                }

                _drone.clip = GetClip(SoundCue.Drone);
                _drone.volume = 0f;
                _drone.Play();
            }

            _droneTarget = target;
            float change = Mathf.Abs(target - _drone.volume);
            _droneFadeSpeed = fadeSeconds > 0.01f ? change / fadeSeconds : float.MaxValue;
        }

        private void StopEverything()
        {
            foreach (AudioSource voice in _voices)
            {
                voice.Stop();
            }

            _drone.Stop();
        }

        /// <summary>Builds the clip for <paramref name="cue"/> the first time it is asked for (a few milliseconds).</summary>
        private AudioClip GetClip(SoundCue cue)
        {
            if (_clips.TryGetValue(cue, out AudioClip clip) && clip != null)
            {
                return clip;
            }

            float[] samples = SfxSynth.Generate(cue);
            clip = AudioClip.Create("Sfx_" + cue, samples.Length, 1, SfxSynth.DefaultSampleRate, false);
            clip.SetData(samples, 0);
            clip.hideFlags = HideFlags.DontSave;
            _clips[cue] = clip;
            return clip;
        }
    }
}
